/* quiz di ecografia ed eco-Doppler (aggiunti a QUIZ3) */
var QUIZ_ECO=[
["eco-principi","In ecografia una raccolta di liquido appare di solito…",["Anecogena (nera), spesso con rinforzo posteriore","Iperecogena con cono d'ombra","Isoecogena al fegato","Invisibile"],0,"Il liquido non produce echi: appare nero e lascia passare bene il fascio (rinforzo dietro)."],
["eco-principi","Perché si mette il gel tra sonda e pelle?",["Per eliminare l'aria, che riflette quasi tutti gli ultrasuoni","Per riscaldare la sonda","Per disinfettare la cute","Per rendere l'immagine a colori"],0,"Tra tessuti molli e aria la riflessione è quasi totale: senza gel l'immagine è nera."],
["eco-principi","Aumentando la frequenza della sonda…",["Migliora la definizione ma si riduce la profondità esplorabile","Aumenta la profondità e peggiora la definizione","Non cambia nulla","Si vedono solo i liquidi"],0,"Per questo si usa la lineare (alta frequenza) per strutture superficiali e la convex per quelle profonde."],
["eco-sonde","Quale sonda scegli per un accesso venoso periferico ecoguidato?",["Lineare ad alta frequenza","Convex a bassa frequenza","Settoriale cardiaca","Endocavitaria"],0,"Le vene degli arti sono superficiali: serve alta definizione nei primi centimetri."],
["eco-sonde","L'immagine è tutta troppo chiara e i vasi sembrano pieni di echi. Che cosa regoli?",["Riduco il guadagno (gain)","Aumento la profondità","Cambio paziente","Aumento il guadagno"],0,"Un guadagno eccessivo crea falsi echi anche nei liquidi."],
["eco-sonde","Che cosa mostra il modo M?",["I movimenti lungo una sola linea dell'immagine nel tempo","La velocità del sangue in un punto","Un'immagine a colori del flusso","Una ricostruzione 3D"],0,"È usato per pleura, vena cava e valvole cardiache."],
["eco-artefatti","Dietro un calcolo della colecisti si vede…",["Un cono d'ombra nero","Un rinforzo luminoso","Linee B","Aliasing"],0,"Il calcolo riflette quasi tutto il fascio: dietro non arrivano ultrasuoni."],
["eco-artefatti","Le linee A sotto la pleura sono…",["Riverberi della linea pleurica, presenti nel polmone aerato","Il segno sicuro di un edema","Vasi sanguigni","Costole"],0,"Sono artefatti orizzontali ripetuti; da sole non escludono il pneumotorace se manca lo scivolamento."],
["eco-doppler","Nella convenzione più usata del color Doppler il rosso indica…",["Flusso verso la sonda","Sangue arterioso","Flusso in allontanamento","Sangue venoso"],0,"Il colore dipende dalla direzione rispetto alla sonda, non dal tipo di vaso: un'arteria può apparire blu."],
["eco-doppler","Perché nel color Doppler di una stenosi compare un mosaico di colori?",["Le velocità superano la scala impostata (aliasing) e c'è turbolenza","La sonda è guasta","Il vaso è occluso","È un segno di vena normale"],0,"Alzando la scala (PRF) l'aliasing si riduce."],
["eco-doppler","Per misurare le velocità con il Doppler l'angolo tra fascio e vaso deve essere…",["60° o meno","Esattamente 90°","Almeno 80°","Non conta"],0,"A 90° il Doppler non registra flusso; oltre 60° l'errore di misura cresce molto."],
["eco-doppler","Il power Doppler è utile soprattutto per…",["Vedere flussi lenti, senza informazione sulla direzione","Misurare la velocità di picco","Vedere l'aria nel torace","Misurare la vescica"],0,"È più sensibile al flusso ma non distingue la direzione."],
["eco-doppler","L'indice di resistenza si calcola come…",["(PSV − EDV) ÷ PSV","PSV × EDV","EDV ÷ frequenza cardiaca","PSV − 100"],0,"Valori alti nelle arterie degli arti a riposo, più bassi in cervello e reni."],
["eco-onde-doppler","L'onda Doppler normale di un'arteria femorale a riposo è…",["Trifasica, con breve inversione del flusso","Monofasica smorzata","Continua con alto flusso diastolico","Fasica con il respiro"],0,"Alta resistenza a valle a riposo: picco rapido, breve flusso invertito, poco flusso diastolico."],
["eco-onde-doppler","Un'onda arteriosa con salita lenta e picco basso e arrotondato indica…",["Una stenosi o occlusione a monte del punto esaminato","Un'arteria normale","Una vena","Un'arteria che porta al cervello"],0,"È l'onda «tardus parvus», tipica dell'arteriopatia periferica."],
["eco-onde-doppler","La carotide interna normale ha un flusso…",["A bassa resistenza, continuo anche in diastole","Trifasico ad alta resistenza","Assente in diastole e invertito","Fasico con il respiro"],0,"Il cervello ha bisogno di flusso continuo."],
["eco-onde-doppler","Nella vena femorale il flusso diventa continuo e piatto, senza variazioni con il respiro. Che cosa sospetti?",["Un'ostruzione più a monte (iliaca o cava)","Una vena normale","Una stenosi carotidea","Un artefatto da gel"],0,"La perdita della fasicità respiratoria indica che il ritorno venoso è ostacolato più in alto."],
["eco-onde-doppler","Che cos'è l'augmentation?",["L'aumento del flusso venoso comprimendo i muscoli a valle","L'aumento del guadagno","Un aumento della velocità arteriosa in sistole","Un tipo di sonda"],0,"Se manca, c'è probabilmente un'ostruzione tra il punto di compressione e quello esaminato."],
["eco-accessi","All'ecografia, come distingui la vena dall'arteria prima di pungere?",["La vena si schiaccia con una lieve pressione e non pulsa; l'arteria è rotonda, pulsante e non si schiaccia","La vena è sempre più grande","L'arteria è sempre blu al color","Non serve distinguerle"],0,"La compressione e il color Doppler evitano la puntura arteriosa."],
["eco-accessi","In asse corto, perché si usa la tecnica di posizionamento dinamico della punta?",["Perché si vede solo una sezione dell'ago e bisogna essere sicuri di seguire la punta, non il corpo","Per andare più veloci","Per evitare il gel","Perché l'ago non è visibile in nessun modo"],0,"Si sposta la sonda finché la punta scompare, poi si avanza l'ago finché ricompare."],
["eco-accessi","Secondo revisioni sistematiche recenti, la guida ecografica per il catetere venoso periferico eseguita da infermieri…",["Aumenta il successo al primo tentativo rispetto alla tecnica tradizionale","Riduce il successo","Non ha alcun effetto","È vietata"],0,"I benefici sono maggiori nelle persone con vene difficili."],
["eco-vescica","Il volume vescicale con la formula dell'ellissoide si calcola come…",["Larghezza × profondità × lunghezza × 0,52","Larghezza + profondità + lunghezza","Lunghezza × 2","Area × 10"],0,"Il risultato in ml approssima bene il volume reale."],
["eco-vescica","Misurare il volume vescicale prima di un cateterismo serve soprattutto a…",["Evitare cateterismi inutili e le infezioni urinarie correlate","Diagnosticare tumori","Sostituire l'esame delle urine","Valutare la funzione renale"],0,"Il cateterismo è un'importante fonte di infezioni correlate all'assistenza."],
["eco-vescica","Quale situazione può falsare la misura del bladder scanner?",["Ascite o cisti pelviche","Il digiuno","Una glicemia alta","La posizione supina"],0,"Il liquido fuori dalla vescica può essere conteggiato come urina."],
["eco-polmone","Linee B diffuse e bilaterali in una persona con scompenso cardiaco indicano…",["Edema polmonare (sindrome interstiziale)","Polmone normale","Pneumotorace","Versamento pericardico"],0,"Tre o più linee B per campo indicano liquido nell'interstizio."],
["eco-polmone","Assenza di scivolamento pleurico, assenza di linee B e linee A presenti fanno sospettare…",["Pneumotorace","Edema polmonare","Polmonite","Polmone normale"],0,"Il «punto polmone» conferma la diagnosi."],
["eco-polmone","In modo M il polmone normale mostra…",["Il segno della riva del mare","Il codice a barre","Solo nero","Un'onda sinusoidale"],0,"Righe orizzontali sopra la pleura e aspetto granulare sotto, per lo scivolamento."],
["eco-fast","Nell'eFAST, qual è la finestra da guardare per prima per il liquido libero?",["Lo spazio epato-renale (Morison)","La tiroide","La carotide","Il ginocchio"],0,"È la zona più declive dell'addome superiore in posizione supina."],
["eco-fast","Una eFAST negativa in un paziente stabile…",["Non esclude lesioni: si ripete e si completa con la TC se indicato","Esclude ogni lesione","Indica sempre la sala operatoria","Permette la dimissione immediata"],0,"La sensibilità non è assoluta, soprattutto nelle prime fasi."],
["eco-vci","Vena cava inferiore di 2,6 cm che collassa meno del 50% in respiro spontaneo indica…",["Pressione dell'atrio destro alta","Ipovolemia","Valori normali","Pneumotorace"],0,"Secondo le raccomandazioni ecocardiografiche corrisponde a circa 15 mmHg."],
["eco-vci","In quale situazione la collassabilità della vena cava non è affidabile?",["Nel paziente in ventilazione meccanica a pressione positiva","Nel paziente sveglio in respiro spontaneo","Nel paziente a digiuno","Nel paziente con la vescica vuota"],0,"La ventilazione a pressione positiva cambia il comportamento della cava con il respiro."],
["eco-tvp","Durante l'ecografia con compressione la vena femorale non si schiaccia. Che cosa indica?",["Trombosi venosa profonda","Vena normale","Arteria normale","Linfonodo"],0,"La vena normale si chiude completamente sotto la sonda."],
["eco-infermiere","Quale di questi è un ambito ecografico diffuso nella pratica infermieristica?",["Accessi venosi ecoguidati e misura del volume vescicale","La diagnosi di tumori epatici","La refertazione dell'ecocardiogramma","La biopsia della prostata"],0,"L'infermiere usa l'ecografia per procedure e controlli mirati, con formazione e protocolli; la diagnosi resta medica."]
];
