/* quiz di ecografia, approfondimenti (aggiunti a QUIZ3) */
var QUIZ_ECO2=[
["eco-semeiotica","Quali caratteristiche definiscono una cisti semplice?",["Nera, pareti sottili e regolari, rinforzo posteriore, nessuna parte solida","Bianca con ombra netta","Grigia con vasi al color Doppler","Pareti spesse e setti irregolari"],0,"Sono i segni del contenuto liquido puro; setti spessi, echi interni o parti solide la rendono «complessa» e da approfondire."],
["eco-semeiotica","Come si distingue all'ecografia un calcolo dal gas?",["Il calcolo dà un'ombra netta e «pulita», il gas un'ombra «sporca» con riverberi","Il gas è nero, il calcolo grigio","Non si possono distinguere","Il calcolo ha rinforzo posteriore"],0,"Entrambi sono bianchi, ma il calcolo assorbe e riflette il fascio in modo uniforme, mentre il gas genera riverberi dentro l'ombra."],
["eco-semeiotica","Perché una struttura va osservata in due piani perpendicolari?",["Perché in un solo piano un vaso tagliato di traverso può sembrare una cisti","Per consumare meno gel","Perché lo impone la legge","Per aumentare la frequenza"],0,"Due piani permettono di capire forma e continuità della struttura."],
["eco-regolazioni","Dove va posizionato il fuoco?",["All'altezza della struttura da studiare","Sempre in superficie","Sempre in fondo allo schermo","Non ha importanza"],0,"Nel fuoco il fascio è più stretto e l'immagine più nitida."],
["eco-regolazioni","Vuoi vedere meglio un organo profondo e l'immagine è scura in basso. Quale regolazione è più corretta?",["Abbassare la frequenza o regolare il TGC delle fasce profonde","Aumentare al massimo il guadagno globale","Passare alla sonda lineare","Ridurre la profondità a 3 cm"],0,"Le frequenze basse penetrano di più; il TGC compensa l'attenuazione senza schiarire le parti superficiali."],
["eco-regolazioni","Che vantaggio offre l'imaging armonico tissutale?",["Immagine più pulita, con meno artefatti nelle strutture liquide","Misura automatica della pressione","Mostra il flusso a colori","Permette di vedere attraverso l'osso"],0,"Usa gli echi a frequenza doppia generati nei tessuti, meno disturbati dagli strati superficiali."],
["eco-regolazioni","I vasi appaiono grigi e pieni di echi su tutta l'immagine. Prima di sospettare un trombo che cosa controlli?",["Il guadagno, che probabilmente è troppo alto, e poi la comprimibilità della vena","La data di nascita del paziente","La temperatura della stanza","Il colore del gel"],0,"Un guadagno eccessivo crea falsi echi nei liquidi."],
["eco-rene","Come appare il seno renale normale?",["Chiaro (iperecogeno) al centro del rene, per il grasso","Nero come la vescica","Assente","Grigio come il muscolo"],0,"Nel rene normale il centro è chiaro; diventa nero e ramificato in caso di idronefrosi."],
["eco-rene","Quale di queste può dilatare i reni senza un vero ostacolo?",["Una vescica molto distesa","Un calcolo nell'uretere","Un tumore della vescica che chiude l'uretere","Un coagulo nel bacinetto"],0,"Anche gravidanza e reflusso possono farlo: per questo si ricontrolla dopo lo svuotamento vescicale."],
["eco-rene","Paziente con idronefrosi da calcolo che sviluppa febbre a 39 °C e brividi. Che cosa fai?",["Avviso subito il medico: un rene ostruito e infetto richiede un drenaggio urgente","Aspetto la prossima ecografia di controllo","Somministro solo un antipiretico e annoto","Faccio bere molto e attendo l'espulsione"],0,"L'infezione a monte di un ostacolo può evolvere rapidamente in sepsi."],
["eco-rene","Che cosa indica l'idronefrosi grave?",["Cavità molto dilatate con corticale assottigliata","Solo il bacinetto lievemente dilatato","Un rene più piccolo ma normale","Una cisti della corticale"],0,"L'assottigliamento della corticale indica un'ostruzione importante o di lunga durata."],
["eco-rene","Al color Doppler compare un luccichio di colori dietro un'immagine bianca del rene. Che cosa suggerisce?",["Un calcolo (artefatto twinkling)","Un'arteria con stenosi","Un tumore molto vascolarizzato","Un errore del gel"],0,"Il twinkling è un artefatto prodotto dalle superfici ruvide dei calcoli."],
["eco-vescica","Si misura il residuo post-minzionale. Quando va eseguita la misura?",["Subito dopo la minzione","Dopo due ore","Prima di urinare","Al mattino seguente"],0,"Aspettare fa riempire di nuovo la vescica e sovrastima il residuo."],
["eco-aorta","Oltre quale diametro l'aorta addominale si definisce aneurismatica?",["3 cm","1,5 cm","2 cm","10 cm"],0,"Normalmente misura circa 2 cm."],
["eco-aorta","Come si misura correttamente il diametro di un aneurisma aortico?",["In scansione trasversale, perpendicolare all'asse del vaso, da parete a parete","Solo il lume colorato al color Doppler","In obliquo, nel punto più lungo","Con la sonda lineare"],0,"Una misura obliqua sovrastima; misurare solo il lume sottostima se c'è trombo murale."],
["eco-aorta","Uomo di 75 anni in shock con dolore lombare e massa pulsante. Quale affermazione è corretta?",["Si presume la rottura dell'aneurisma e si attiva subito la chirurgia, anche se l'ecografia non mostra l'ematoma","Si aspetta una TC programmata","Si somministrano grandi volumi per riportare subito la PA a 130","È una colica renale, basta l'analgesia"],0,"L'ecografia vede male il retroperitoneo; nell'attesa si mantiene una pressione bassa ma sufficiente."],
["eco-aorta","Quale fattore di rischio è più importante per l'aneurisma dell'aorta addominale?",["Il fumo","La miopia","Il gruppo sanguigno","L'ipotiroidismo"],0,"Contano anche sesso maschile, età avanzata, ipertensione e familiarità."],
["eco-aorta","Che cos'è un endoleak?",["Un flusso che continua a riempire la sacca dopo un'endoprotesi aortica","Una perdita di urina dal catetere","Un versamento pleurico","Un'infezione della ferita"],0,"Va sorvegliato perché può far crescere di nuovo la sacca."],
["eco-pocus","Che cosa valuta il protocollo RUSH nello shock?",["Pompa (cuore), serbatoio (cava, liquido libero, polmone) e tubi (aorta, vene profonde)","Solo il fegato","Solo il polmone","La vescica e la prostata"],0,"Aiuta a distinguere shock ipovolemico, cardiogeno, ostruttivo e distributivo."],
["eco-pocus","Durante una rianimazione cardiopolmonare, quando si esegue l'ecografia?",["Nelle brevi pause previste per il controllo del ritmo, senza prolungarle","Interrompendo il massaggio per alcuni minuti","Prima di iniziare le compressioni","Mai"],0,"Le interruzioni delle compressioni vanno ridotte al minimo; l'ecografia cerca attività cardiaca e cause reversibili."],
["eco-pocus","Una FAST negativa in un traumatizzato stabile significa che…",["Non c'è liquido visibile in quel momento, ma non esclude lesioni: si ripete se il quadro cambia","Il paziente può essere dimesso subito","Non servono altri esami","Il sangue è stato riassorbito"],0,"La sensibilità della FAST non è assoluta, soprattutto per lesioni retroperitoneali o di organi cavi."],
["eco-procedure","Nell'approccio in asse lungo (in-plane) l'ago…",["Si vede per intero, punta compresa","Appare come un punto bianco","Non si vede mai","Si vede solo con il color Doppler"],0,"Entra nel piano del fascio dal lato corto della sonda."],
["eco-procedure","Qual è il rischio tipico dell'asse corto (out-of-plane)?",["Scambiare il corpo dell'ago per la punta e avanzare troppo","Non vedere la vena","Rompere la sonda","Contaminare il gel"],0,"Per questo si inclina la sonda seguendo la punta, o si passa all'asse lungo."],
["eco-procedure","Che cosa serve per una procedura invasiva ecoguidata?",["Copri-sonda e gel sterili, oltre alla normale antisepsi della cute","Solo gel normale","Nessuna precauzione","Sonda lavata con acqua"],0,"La sonda entra nel campo sterile e va protetta."],
["eco-procedure","Che differenza c'è tra tecnica eco-assistita e guida in tempo reale?",["Nell'eco-assistita si marca il punto e poi si procede senza sonda; in tempo reale si segue l'ago sullo schermo","Sono la stessa cosa","L'eco-assistita usa la TC","La guida in tempo reale non usa ultrasuoni"],0,"La guida in tempo reale permette di correggere il percorso in ogni momento."],
["eco-procedure","Dopo una paracentesi abbondante quale parametro sorvegli con particolare attenzione?",["La pressione arteriosa","Il colore degli occhi","La glicemia capillare ogni 5 minuti","L'altezza"],0,"La rimozione di grandi volumi può causare ipotensione; si sorvegliano anche il sito e la quantità drenata."]
];
