/* quiz di triage da protocolli (lotto 1, aggiunti a QUIZ3) */
var QUIZ_TRI1=[
["tri-allergia","Un paziente ha gonfiore della lingua e voce rauca dopo una puntura. Quale livello di triage gli assegni?",["Livello 2: rischio alto, il respiro può peggiorare rapidamente","Livello 5: non urgente","Livello 4: urgenza semplice","Livello 3: urgente con attesa"],0,"Il gonfiore della gola e la voce rauca indicano un rischio per le vie aeree: si classifica come rischio alto, senza aspettare."],
["tri-allergia","Nell'anafilassi, quale farmaco va somministrato per primo?",["Adrenalina per via intramuscolare","Antistaminico per bocca","Cortisone per via endovenosa","Paracetamolo"],0,"L'adrenalina intramuscolo è il trattamento di prima scelta; gli antistaminici e i cortisonici sono di supporto e non sostituiscono l'adrenalina."],
["tri-stato-mentale","Un paziente diabetico è confuso e sudato. Qual è il primo controllo da fare?",["Glicemia capillare","Temperatura corporea","Peso","Gruppo sanguigno"],0,"La confusione in un diabetico può dipendere dall'ipoglicemia, che si corregge in pochi minuti: la glicemia va misurata subito."],
["tri-stato-mentale","Un paziente con cefalea, febbre e collo rigido arriva in triage sveglio. Come lo consideri?",["Sospetto di meningite, da trattare come urgenza","Cefalea da stress, livello 5","Febbre semplice","Disturbo muscolare del collo"],0,"La triade di cefalea, febbre e rigidità del collo richiede di sospettare una meningite, che va trattata come urgenza."],
["tri-respiro","Un paziente parla a frasi brevi, con sibili e saturazione del 92% in aria. Quale affermazione è corretta?",["Il paziente è a rischio alto: parole brevi e sibili indicano difficoltà respiratoria","Il paziente è a rischio basso se la saturazione è sopra 90%","La saturazione da sola basta a classificarlo","Basta osservare che respira"],0,"Il numero di parole in una frase e i sibili sono segni di difficoltà respiratoria che alzano il livello, anche se la saturazione non è critica."],
["tri-respiro","Perché in un paziente con BPCO l'obiettivo di saturazione può essere più basso?",["Per il rischio di accumulo di anidride carbonica con ossigeno ad alta concentrazione","Perché la BPCO non riduce la saturazione","Perché l'ossigeno non serve","Per evitare l'uso dei sibili"],0,"Nei pazienti con BPCO un eccesso di ossigeno può rallentare il respiro e far salire la CO2: si segue l'obiettivo del protocollo."],
["tri-ustioni","Con la regola del nove, quanto vale un arto superiore in un adulto?",["Circa il 9%","Circa il 1%","Circa il 18%","Circa il 27%"],0,"Negli adulti ogni arto superiore vale circa il 9% della superficie corporea; la regola serve a stimare l'estensione."],
["tri-ustioni","Un'ustione bianca e indolore sul braccio: che cosa indica?",["Una lesione profonda, perché le terminazioni nervose sono distrutte","Una scottatura superficiale","Un'ustione da sole","Un'ustione senza danno"],0,"Un'ustione bianca e senza dolore è spesso profonda: la perdita di sensibilità è un segno di distruzione dei tessuti."],
["tri-dolore-toracico","Un uomo di 60 anni, diabetico, ha nausea e stanchezza intensa ma poco dolore al petto. Che cosa fai?",["Procuri subito un ECG e lo segnali al medico","Gli dici di riposare e aspettare","Lo mandi a casa con un antiacido","Lo fai aspettare in fila"],0,"Nei diabetici e negli anziani il dolore cardiaco può essere atipico: la nausea e la stanchezza richiedono comunque un ECG rapido."],
["tri-dolore-toracico","Un dolore toracico che peggiora premendo sulla parete e con il movimento è più spesso:",["Di origine muscolare o parietale, ma va comunque valutato","Sempre un infarto","Sempre un'embolia","Un normale sintomo di età"],0,"Il dolore che cambia con il movimento o la pressione è più spesso parietale; resta un sintomo da valutare, perché non esclude altre cause."]
];
